    await expect(page.getByText(testShowName).first()).toBeVisible();
    // Now search for something that can't match our show
    await page.getByPlaceholder("Search shows...").fill("ZZZNOTASHOW999");
    await expect(page.getByText(testShowName)).not.toBeVisible();
  });

  test("empty state shows informative message when no shows match the query", async ({
    page,
  }) => {
    await page.getByPlaceholder("Search shows...").fill("ZZZNOTASHOW999");
    await expect(page.getByText(/no shows match/i)).toBeVisible();
  });

  // ─── Clearing ───────────────────────────────────────────────────────────────

  test("× button clears search, resets URL to /, and restores the full list", async ({
    page,
  }) => {
    const input = page.getByPlaceholder("Search shows...");
    await input.fill("ZZZNOTASHOW999");
    await expect(page.getByText(/no shows match/i)).toBeVisible();

    await page.getByRole("button", { name: /clear search/i }).click();

    await expect(page).toHaveURL("/");
    await expect(input).toHaveValue("");
    await expect(page.getByText(/no shows match/i)).not.toBeVisible();
    // The show we created should be back
    await expect(page.getByText(testShowName).first()).toBeVisible();
  });

  test("Escape key clears the search input and navigates back to /", async ({ page }) => {
    const input = page.getByPlaceholder("Search shows...");
    await input.fill("IMEX");
    await expect(page).toHaveURL(/\?q=/);

    await input.press("Escape");

    await expect(page).toHaveURL("/");
    await expect(input).toHaveValue("");
  });

  // ─── Cross-page navigation ──────────────────────────────────────────────────

  test("Enter key on a non-dashboard page navigates to /?q=<term>", async ({ page }) => {
    await page.goto("/calendar");
    await waitForApp(page);

    const input = page.getByPlaceholder("Search shows...");
    await input.fill("IMEX");
    await input.press("Enter");

    await expect(page).toHaveURL(/\?q=IMEX/);
    // Should now be on the dashboard
    await waitForApp(page);
    await expect(page.getByText(/active shows/i)).toBeVisible();
  });

  test("Enter key on dashboard with empty input navigates to /", async ({ page }) => {
    // Start with a query in the URL
    await page.goto("/?q=IMEX");
    await waitForApp(page);
    const input = page.getByPlaceholder("Search shows...");
    await input.clear();
    await input.press("Enter");
    await expect(page).toHaveURL("/");
  });
});

import { useState, useMemo, useEffect } from "react";
import { Link, useSearch } from "wouter";
import { differenceInDays, startOfDay } from "date-fns";
import { 
  useListShows, 
  useGetDashboardSummary 
} from "@workspace/api-client-react";
import { ShowCard } from "@/components/show-card";
import { Layout } from "@/components/layout";
import { AddShowDialog } from "@/components/add-show-dialog";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from "@/components/ui/select";
import { AlertCircle, ChevronDown, ChevronUp } from "lucide-react";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Card, CardContent } from "@/components/ui/card";
import { formatDate, parseDateStr } from "@/lib/date-utils";
import { DashboardWeeklyCalendar } from "@/components/dashboard-weekly-calendar";
import { OverduePanel } from "@/components/overdue-panel";

type SortOption = "date-asc" | "date-desc" | "name" | "overdue";

export default function Dashboard() {
  const { data: shows, isLoading: showsLoading } = useListShows();
  const { data: summary, isLoading: summaryLoading } = useGetDashboardSummary();
  const [sortBy, setSortBy] = useState<SortOption>("date-asc");
  const [archivedOpen, setArchivedOpen] = useState(false);

  const searchQuery = new URLSearchParams(useSearch()).get("q")?.trim() ?? "";

  const today = startOfDay(new Date());

  const matchesSearch = (s: { name: string; venue?: string | null }, q: string) => {
    const lower = q.toLowerCase();
    return s.name.toLowerCase().includes(lower) || (s.venue ?? "").toLowerCase().includes(lower);
  };

  const activeShows = useMemo(() => {
    if (!shows) return [];
    return shows.filter(s => {
      const cutoff = startOfDay(parseDateStr(s.dismantleDate ?? s.moveInDate));
      return differenceInDays(cutoff, today) >= 0;
    }).filter(s => !searchQuery || matchesSearch(s, searchQuery))
      .sort((a, b) => {
        if (sortBy === "date-asc") {
          return parseDateStr(a.moveInDate).getTime() - parseDateStr(b.moveInDate).getTime();
        }
        if (sortBy === "date-desc") {
          return parseDateStr(b.moveInDate).getTime() - parseDateStr(a.moveInDate).getTime();
        }
        if (sortBy === "name") {
          return a.name.localeCompare(b.name);
        }
        if (sortBy === "overdue") {
          return (b.overdueCount || 0) - (a.overdueCount || 0);
        }
        return 0;
      });
  }, [shows, sortBy, today, searchQuery]);

  const archivedShows = useMemo(() => {
    if (!shows) return [];
    return shows.filter(s => {
      const cutoff = startOfDay(parseDateStr(s.dismantleDate ?? s.moveInDate));
      return differenceInDays(cutoff, today) < 0;
    }).filter(s => !searchQuery || matchesSearch(s, searchQuery))
      .sort((a, b) => parseDateStr(b.moveInDate).getTime() - parseDateStr(a.moveInDate).getTime());
  }, [shows, today, searchQuery]);

  useEffect(() => {
    if (searchQuery && archivedShows.length > 0) setArchivedOpen(true);
  }, [searchQuery, archivedShows.length]);

  return (
    <Layout>
      <div className="container mx-auto p-4 md:p-6 space-y-8">

        {/* Next Up Banner */}
        {!summaryLoading && summary?.nextUpShow && (
          <div className="bg-primary/10 border border-primary/20 rounded-lg p-6 flex flex-col md:flex-row items-center justify-between gap-6">
            <div className="flex items-center gap-4">
              <div className="bg-primary/20 p-4 rounded-full">
                <AlertCircle className="h-8 w-8 text-primary" />
              </div>
              <div>
                <h2 className="text-sm font-semibold text-primary uppercase tracking-wider">Next Up</h2>
                <Link href={`/shows/${summary.nextUpShow.id}`} className="text-2xl font-bold hover:underline">
                  {summary.nextUpShow.name}
                </Link>
                <div className="text-muted-foreground mt-1">
                  Move-in: {formatDate(summary.nextUpShow.moveInDate)}
                  {summary.nextUpShow.venue && ` • ${summary.nextUpShow.venue}`}
                </div>
              </div>
            </div>

            <div className="text-center bg-background rounded-lg p-4 shadow-sm border min-w-[200px]">
              <div className="text-5xl font-black text-primary">
                {Math.abs(differenceInDays(startOfDay(parseDateStr(summary.nextUpShow.moveInDate)), today))}
              </div>
              <div className="text-sm font-medium text-muted-foreground uppercase tracking-wider mt-1">
                Days Until Move-in
              </div>
            </div>
          </div>
        )}

        {summaryLoading && (
          <Skeleton className="w-full h-32 rounded-lg" />
        )}

        {/* Weekly Calendar */}
        <DashboardWeeklyCalendar />

        {/* Overdue Panel */}
        <OverduePanel />

        {/* Dashboard Header */}
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Active Shows</h1>
            <span className="text-muted-foreground mt-1 block">
              {summaryLoading ? <Skeleton className="w-32 h-5 inline-block" /> : `${summary?.activeShows || 0} active, ${summary?.totalOverdue || 0} items overdue`}
            </span>
          </div>

          <div className="flex items-center gap-3">
            <Select value={sortBy} onValueChange={(val) => setSortBy(val as SortOption)}>
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="Sort by..." />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="date-asc">Date (Earliest First)</SelectItem>
                <SelectItem value="date-desc">Date (Latest First)</SelectItem>
                <SelectItem value="name">Name (A-Z)</SelectItem>
                <SelectItem value="overdue">Most Overdue</SelectItem>
              </SelectContent>
            </Select>

            <AddShowDialog />
          </div>
        </div>

        {/* Active Shows Grid */}
        {showsLoading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[1, 2, 3].map(i => (
              <Skeleton key={i} className="h-[250px] rounded-xl" />
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {activeShows.map(show => (
              <ShowCard key={show.id} show={show} />
            ))}
            {activeShows.length === 0 && (
              <div className="col-span-full py-12 text-center border-2 border-dashed rounded-xl text-muted-foreground">
                {searchQuery ? `No shows match "${searchQuery}".` : "No active shows found. Add one to get started."}
              </div>
            )}
          </div>
        )}

        {/* Archived Shows */}
        {archivedShows.length > 0 && (
          <Collapsible
            open={archivedOpen}
            onOpenChange={setArchivedOpen}
            className="mt-12 space-y-4"
          >
            <div className="flex items-center justify-between">
              <h2 className="text-2xl font-bold tracking-tight text-muted-foreground">Archived Shows</h2>
              <CollapsibleTrigger asChild>
                <Button variant="ghost" size="sm">
                  {archivedOpen ? "Hide" : "Show"} ({archivedShows.length})
                  {archivedOpen ? <ChevronUp className="ml-2 h-4 w-4" /> : <ChevronDown className="ml-2 h-4 w-4" />}
                </Button>
              </CollapsibleTrigger>
            </div>

            <CollapsibleContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 opacity-75 hover:opacity-100 transition-opacity">
                {archivedShows.map(show => (
                  <ShowCard key={show.id} show={show} />
                ))}
              </div>
            </CollapsibleContent>
          </Collapsible>
        )}

      </div>
    </Layout>
  );
}

import { test, expect, Page } from "@playwright/test";

async function waitForApp(page: Page) {
  await page.waitForFunction(
    () => document.documentElement.style.visibility !== "hidden",
    { timeout: 10_000 },
  );
}

async function getFirstShowUrl(page: Page): Promise<string | null> {
  const link = page.locator('a[href^="/shows/"]').first();
  return (await link.count()) > 0 ? link.getAttribute("href") : null;
}

async function addTaskWithCategory(page: Page, name: string, category: string) {
  await page.getByRole("button", { name: /add task/i }).click();
  const dialog = page.getByRole("dialog");
  await dialog.getByRole("tab", { name: /custom/i }).click();
  await dialog.getByLabel("Task Name *").fill(name);
  // The category Select is the only combobox in this form
  await dialog.getByRole("combobox").click();
  await page.getByRole("option", { name: category }).click();
  await dialog.getByRole("button", { name: /add custom task/i }).click();
  await expect(dialog).not.toBeVisible({ timeout: 10_000 });
}

test.describe("Task toolbar — Filter / Sort / Group", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/");
    await waitForApp(page);
    const href = await getFirstShowUrl(page);
    test.skip(!href, "No shows exist");
    await page.goto(href!);
    await waitForApp(page);
    // Tasks tab is the default
  });

  // ─── Toolbar ─────────────────────────────────────────────────────────────

  test("toolbar renders with all controls when tasks exist", async ({ page }) => {
    await addTaskWithCategory(page, `Toolbar Test ${Date.now()}`, "Electrical");
    const toolbar = page.locator('[data-testid="task-toolbar"]');
    await expect(toolbar).toBeVisible();
    await expect(toolbar.getByRole("button", { name: /^filter/i })).toBeVisible();
    await expect(toolbar.getByRole("combobox")).toBeVisible();
    await expect(toolbar.getByRole("button", { name: "Status" })).toBeVisible();
    await expect(toolbar.getByRole("button", { name: "Category" })).toBeVisible();
  });

  // ─── Filter ──────────────────────────────────────────────────────────────

  test.describe("Filter", () => {
    test.beforeEach(async ({ page }) => {
      // Ensure at least one categorised task exists for filter tests
      await addTaskWithCategory(page, `Filter Task ${Date.now()}`, "Fire Marshal");
    });

    test("Filter popover lists all 6 categories", async ({ page }) => {
      await page
        .locator('[data-testid="task-toolbar"]')
        .getByRole("button", { name: /^filter/i })
        .click();
      // Popover items have cursor-pointer + select-none; task rows do not
      for (const cat of [
        "Fire Marshal",
        "ID Sign",
        "Warehouse Manifest",
        "Show Bucket",
        "Vehicle Spotting",
        "Electrical",
      ]) {
        await expect(
          page.locator(".cursor-pointer.select-none").filter({ hasText: cat }),
        ).toBeVisible();
      }
    });

    test("selecting a category shows a count badge on the Filter button", async ({ page }) => {
      const toolbar = page.locator('[data-testid="task-toolbar"]');
      await toolbar.getByRole("button", { name: /^filter/i }).click();
      await page
        .locator(".cursor-pointer.select-none")
        .filter({ hasText: "Fire Marshal" })
        .click();
      await page.keyboard.press("Escape");
      await expect(toolbar.getByRole("button", { name: /^filter/i })).toContainText("1");
    });

    test("selecting a category shows a dismissible chip in the toolbar", async ({ page }) => {
      const toolbar = page.locator('[data-testid="task-toolbar"]');
      await toolbar.getByRole("button", { name: /^filter/i }).click();
      await page
        .locator(".cursor-pointer.select-none")
        .filter({ hasText: "Fire Marshal" })
        .click();
      await page.keyboard.press("Escape");
      // Chip is a cursor-pointer element inside the toolbar containing the category name
      await expect(
        toolbar.locator('[class*="cursor-pointer"]').filter({ hasText: "Fire Marshal" }).first(),
      ).toBeVisible();
    });

    test("clicking a chip removes that filter", async ({ page }) => {
      const toolbar = page.locator('[data-testid="task-toolbar"]');
      await toolbar.getByRole("button", { name: /^filter/i }).click();
      await page
        .locator(".cursor-pointer.select-none")
        .filter({ hasText: "Fire Marshal" })
        .click();
      await page.keyboard.press("Escape");
      // Click the chip to dismiss it
      await toolbar
        .locator('[class*="cursor-pointer"]')
        .filter({ hasText: "Fire Marshal" })
        .first()
        .click();
      await expect(toolbar.getByRole("button", { name: /^filter/i })).not.toContainText("1");
    });

    test("Clear all removes all active filters at once", async ({ page }) => {
      const toolbar = page.locator('[data-testid="task-toolbar"]');
      await toolbar.getByRole("button", { name: /^filter/i }).click();
      await page
        .locator(".cursor-pointer.select-none")
        .filter({ hasText: "Fire Marshal" })
        .click();
      await page
        .locator(".cursor-pointer.select-none")
        .filter({ hasText: "ID Sign" })
        .click();
      await page.getByRole("button", { name: /clear all/i }).click();
      await page.keyboard.press("Escape");
      await expect(toolbar.getByRole("button", { name: /^filter/i })).not.toContainText("2");
    });

    test("active filter hides tasks whose category does not match", async ({ page }) => {
      const electricalName = `Non-FM Task ${Date.now()}`;
      await addTaskWithCategory(page, electricalName, "Electrical");
      const toolbar = page.locator('[data-testid="task-toolbar"]');
      await toolbar.getByRole("button", { name: /^filter/i }).click();
      await page
        .locator(".cursor-pointer.select-none")
        .filter({ hasText: "Fire Marshal" })
        .click();
      await page.keyboard.press("Escape");
      // The Electrical task (unique name) should no longer be visible
      await expect(page.getByText(electricalName)).not.toBeVisible();
    });
  });

  // ─── Sort ─────────────────────────────────────────────────────────────────

  test("sort dropdown has all 4 options", async ({ page }) => {
    await addTaskWithCategory(page, `Sort Test ${Date.now()}`, "Show Bucket");
    const toolbar = page.locator('[data-testid="task-toolbar"]');
    await toolbar.getByRole("combobox").click();
    await expect(page.getByRole("option", { name: "Due Date ↑" })).toBeVisible();
    await expect(page.getByRole("option", { name: "Due Date ↓" })).toBeVisible();
    await expect(page.getByRole("option", { name: "Name A→Z" })).toBeVisible();
    await expect(page.getByRole("option", { name: "Category" })).toBeVisible();
  });

  test("changing sort to Name A→Z rerenders without error", async ({ page }) => {
    await addTaskWithCategory(page, `Sort Name Test ${Date.now()}`, "ID Sign");
    const toolbar = page.locator('[data-testid="task-toolbar"]');
    await toolbar.getByRole("combobox").click();
    await page.getByRole("option", { name: "Name A→Z" }).click();
    await expect(page.locator('[role="checkbox"]').first()).toBeVisible();
  });

  // ─── Group ────────────────────────────────────────────────────────────────

  test("Status is the active group mode by default", async ({ page }) => {
    await addTaskWithCategory(page, `Group Default ${Date.now()}`, "Electrical");
    const toolbar = page.locator('[data-testid="task-toolbar"]');
    await expect(toolbar.getByRole("button", { name: "Status" })).toHaveClass(/bg-primary/);
    await expect(toolbar.getByRole("button", { name: "Category" })).not.toHaveClass(/bg-primary/);
  });

  test("switching to Category mode activates the Category button", async ({ page }) => {
    await addTaskWithCategory(page, `Cat Mode ${Date.now()}`, "Electrical");
    const toolbar = page.locator('[data-testid="task-toolbar"]');
    await toolbar.getByRole("button", { name: "Category" }).click();
    await expect(toolbar.getByRole("button", { name: "Category" })).toHaveClass(/bg-primary/);
    await expect(toolbar.getByRole("button", { name: "Status" })).not.toHaveClass(/bg-primary/);
  });

  test("Category mode shows a collapsible section for each task's category", async ({ page }) => {
    const taskName = `Section Task ${Date.now()}`;
    await addTaskWithCategory(page, taskName, "Electrical");
    const toolbar = page.locator('[data-testid="task-toolbar"]');
    await toolbar.getByRole("button", { name: "Category" }).click();
    // The "Electrical" section header should appear
    await expect(
      page
        .locator(".font-semibold.uppercase.tracking-wider")
        .filter({ hasText: "Electrical" })
        .first(),
    ).toBeVisible();
    // The task itself should be visible inside the section
    await expect(page.getByText(taskName)).toBeVisible();
  });

  test("category sections start expanded and collapse on button click", async ({ page }) => {
    const taskName = `Collapse Task ${Date.now()}`;
    await addTaskWithCategory(page, taskName, "Fire Marshal");
    const toolbar = page.locator('[data-testid="task-toolbar"]');
    await toolbar.getByRole("button", { name: "Category" }).click();
    // Confirm task is visible while section is open
    await expect(page.getByText(taskName)).toBeVisible();
    // Click the collapse button in the Fire Marshal section header
    const sectionHeader = page
      .locator(".flex.items-center.justify-between")
      .filter({ hasText: "Fire Marshal" })
      .first();
    await sectionHeader.getByRole("button").click();
    await page.waitForTimeout(300); // collapse animation
    await expect(page.getByText(taskName)).not.toBeVisible();
  });

  test("switching back to Status restores Status as the active mode", async ({ page }) => {
    await addTaskWithCategory(page, `Back To Status ${Date.now()}`, "ID Sign");
    const toolbar = page.locator('[data-testid="task-toolbar"]');
    await toolbar.getByRole("button", { name: "Category" }).click();
    await toolbar.getByRole("button", { name: "Status" }).click();
    await expect(toolbar.getByRole("button", { name: "Status" })).toHaveClass(/bg-primary/);
    await expect(toolbar.getByRole("button", { name: "Category" })).not.toHaveClass(/bg-primary/);
  });
});

